def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    colored = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, bg)]
    if not colored:
        return [row[:] for row in grid]

    r0 = min(r for r, c in colored)
    c0 = min(c for r, c in colored)
    shape = [(r-r0, c-c0) for r, c in colored]
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1
    color = grid[r0][c0]

    out = [row[:] for row in grid]
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if all(grid[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = color
    return out
